"""L300 variance reduction: expected overtime of a warehouse picking shift, with fewer runs for the same precision.

A shift has 12 picking tasks, each ~ exponential(mean 0.6 h); overtime = max(0, total - 7 h).
The exact answer is known (Erlang formula), so every estimator can be checked against it.
python variance_reduction.py
"""
import math

import numpy as np

N_TASKS, MEAN_H, SHIFT_H, SEED = 12, 0.6, 7.0, 2026


def overtime(u, shift=SHIFT_H):
    """Model: uniforms (n, 12) -> overtime hours. Inverse transform t = -mean*ln(1-u) is monotone in every u."""
    t = -MEAN_H * np.log1p(-u)
    return np.maximum(t.sum(axis=1) - shift, 0.0), t.sum(axis=1)


def exact_overtime(k=N_TASKS, mean=MEAN_H, s=SHIFT_H):
    """E[(T - s)+] for T ~ Erlang(k, rate 1/mean) = k*mean*P(Erlang(k+1) > s) - s*P(Erlang(k) > s)."""
    tail = lambda m: sum(math.exp(-s / mean) * (s / mean) ** j / math.factorial(j) for j in range(m))
    return k * mean * tail(k + 1) - s * tail(k)


def summary(y, evals):
    """Mean, standard error and per-evaluation variance (the cost-fair number to compare methods by)."""
    se = float(np.std(y, ddof=1) / math.sqrt(len(y)))
    return {"mean": float(np.mean(y)), "se": se, "var_per_eval": se ** 2 * evals}


def plain(n, seed=SEED):
    y, _ = overtime(np.random.default_rng(seed).random((n, N_TASKS)))
    return summary(y, n)


def antithetic(n, seed=SEED):
    """One stream per PAIR: f(u) and f(1-u) share the same u, so their errors cancel (Owen 8.2)."""
    u = np.random.default_rng(seed).random((n // 2, N_TASKS))
    a, b = overtime(u)[0], overtime(1.0 - u)[0]
    out = summary((a + b) / 2, n)  # analyse PAIR averages: the two halves of a pair are not independent
    return out | {"rho": float(np.corrcoef(a, b)[0, 1])}


def antithetic_loop(n, seed=SEED):
    """Loop version, as when a simulator is called once per run: evaluate f(u) and its mirror f(1-u) per pair."""
    a, b = np.empty(n // 2), np.empty(n // 2)
    for i in range(n // 2):
        a[i] = overtime(np.random.default_rng([2 * i, seed]).random((1, N_TASKS)))[0][0]  # a fresh stream per call
        b[i] = overtime(1.0 - np.random.default_rng([2 * i + 1, seed]).random((1, N_TASKS)))[0][0]
    return summary((a + b) / 2, n) | {"rho": float(np.corrcoef(a, b)[0, 1])}


def control_variate(n, seed=SEED):
    """Y - beta*(C - E[C]) with C = total task time, whose mean 12*0.6 = 7.2 h is known exactly."""
    y, c = overtime(np.random.default_rng(seed).random((n, N_TASKS)))
    beta = np.cov(y, c)[0, 1] / np.var(c, ddof=1)  # optimal beta = Cov(Y, C) / Var(C)
    return summary(y - beta * (c - N_TASKS * MEAN_H), n) | {"beta": float(beta)}


def crn_difference(n, seed=SEED, crn=True):
    """Recap (L200 #11): overtime saved by a 30-minute longer shift, same vs independent random numbers."""
    rng = np.random.default_rng(seed)
    u7 = rng.random((n, N_TASKS))
    u75 = u7 if crn else rng.random((n, N_TASKS))
    return summary(overtime(u7)[0] - overtime(u75, shift=7.5)[0], n)


def main(n=20_000):
    print(f"exact expected overtime: {exact_overtime():.4f} h per shift (Erlang formula)")
    base = plain(n)
    print(f"{n:,} model evaluations per method:")
    print("  method              estimate   std.err   variance ratio vs plain")
    rows = [("plain Monte Carlo", base), ("antithetic", antithetic(n)), ("control variate", control_variate(n)),
            ("antithetic (loop)", antithetic_loop(n))]
    for name, r in rows:
        extra = f"  rho={r['rho']:+.2f}" if "rho" in r else f"  beta={r['beta']:.3f}" if "beta" in r else ""
        print(f"  {name:18s}  {r['mean']:.4f}    {r['se']:.5f}   {base['var_per_eval'] / r['var_per_eval']:5.2f}x{extra}")
    ind, com = crn_difference(n, crn=False), crn_difference(n)
    print(f"CRN recap, overtime saved by a 7.5 h shift: independent {ind['mean']:.4f} +/- {1.96 * ind['se']:.4f}, "
          f"common {com['mean']:.4f} +/- {1.96 * com['se']:.4f} h")


if __name__ == "__main__":
    main()

"""L300 calibration: fit a room cool-down model to a logged temperature curve, and validate it honestly.

An office's heating switches off at 18:00; a sensor logs the room every 10 minutes for 12 hours.
Three candidate models are calibrated by least squares on the first 8 hours and checked on the last 4.
python calibrate.py
"""
import numpy as np

SEED, NOISE = 13, 0.15
T_HOURS = np.arange(0, 12 + 1e-9, 1 / 6)  # 73 readings, every 10 minutes
CAL = T_HOURS <= 8.0  # calibration window; the rest (8-12 h) is the holdout


def observed(seed=SEED):
    """Synthetic 'measured' data: fast air mode (1.5 h) + slow wall mode (9 h) + sensor noise. Truth is known."""
    truth = 12 + 6 * np.exp(-T_HOURS / 1.5) + 4 * np.exp(-T_HOURS / 9.0)
    return truth + np.random.default_rng(seed).normal(0, NOISE, T_HOURS.size)


def one_exp(t, p):  # [T_inf, A, tau]: Newton cooling, one time constant (3 parameters)
    return p[0] + p[1] * np.exp(-t / p[2])


def two_exp(t, p):  # [T_inf, A, tau_air, B, tau_wall]: air + walls (5 parameters)
    return p[0] + p[1] * np.exp(-t / p[2]) + p[3] * np.exp(-t / p[4])


def gauss_newton(model, t, y, p0, iters=200, lam=1e-3):
    """Least squares: minimise sum (model - y)^2 with damped Gauss-Newton (Levenberg-Marquardt) steps."""
    p = np.array(p0, float)
    cost = lambda q: float(np.sum((model(t, q) - y) ** 2))
    for _ in range(iters):
        r = model(t, p) - y
        J = np.column_stack([(model(t, p + h) - model(t, p)) / h[i]  # forward-difference Jacobian
                             for i, h in enumerate(np.diag(1e-6 * np.maximum(1.0, np.abs(p))))])
        step = np.linalg.solve(J.T @ J + lam * np.diag(np.diag(J.T @ J)), -J.T @ r)
        if cost(p + step) < cost(p):
            p, lam = p + step, lam / 3  # accept, trust the quadratic model more
        else:
            lam *= 5  # reject, take smaller steps
        if np.linalg.norm(step) < 1e-10 * (1 + np.linalg.norm(p)):
            break
    return p, J


def poly(degree):
    """Black-box curve: polynomial in t/8 (7 parameters for degree 6) - flexible, but no physics."""
    def fit(t, y):
        coef = np.linalg.lstsq(np.vander(t / 8, degree + 1), y)[0]
        return lambda tt: np.vander(tt / 8, degree + 1) @ coef
    return fit


def candidates(t, y):
    """Calibrate each model on (t, y); return name -> (n_params, predict function)."""
    p1, _ = gauss_newton(one_exp, t, y, [y[-1], y[0] - y[-1], 2.0])
    p2, _ = gauss_newton(two_exp, t, y, [y[-1], 5.0, 1.0, 5.0, 6.0])
    return {"one-exp (3 p)": (3, lambda tt: one_exp(tt, p1)),
            "two-exp (5 p)": (5, lambda tt: two_exp(tt, p2)),
            "poly-6 (7 p)": (7, poly(6)(t, y))}


rmse = lambda a, b: float(np.sqrt(np.mean((a - b) ** 2)))


def scores(models, y, mask):
    """RMSE of every calibrated model on the readings selected by mask."""
    return {name: rmse(f(T_HOURS[mask]), y[mask]) for name, (_, f) in models.items()}


def select(y):
    """Calibrate every candidate on the first 8 h, score them and return the best."""
    models = candidates(T_HOURS[CAL], y[CAL])
    s = scores(models, y, CAL)  # score each model on the readings it was fitted to
    return min(s, key=s.get), s, models


def main():
    y = observed()
    print(f"{y.size} readings, {CAL.sum()} for calibration (0-8 h), {(~CAL).sum()} held out (8-12 h); "
          f"sensor noise sd {NOISE}")
    best, _, models = select(y)
    same, hold = scores(models, y, CAL), scores(models, y, ~CAL)
    print("  model           RMSE on calibration data   RMSE on holdout   prediction at 12 h (measured "
          f"{y[-1]:.2f})")
    for name, (_, f) in models.items():
        print(f"  {name:14s}  {same[name]:10.3f} C               {hold[name]:8.3f} C      {f(T_HOURS[-1:])[0]:8.2f} C")
    print(f"select() picks {best}; its holdout RMSE is {hold[best]:.3f} C")


if __name__ == "__main__":
    main()
